const A={user:null,csrf:'',view:'dashboard',data:{}};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function toast(m,type=''){const w=document.querySelector('.toast-wrap')||(()=>{const d=document.createElement('div');d.className='toast-wrap';document.body.appendChild(d);return d})();const t=document.createElement('div');t.className='toast '+type;t.textContent=m;w.appendChild(t);setTimeout(()=>t.remove(),3000)}
async function runAction(btn,fn){if(!btn||btn.disabled)return;btn.disabled=true;btn.classList.add('is-busy');try{return await fn()}catch(e){toast(e.message||'Action failed','error')}finally{btn.disabled=false;btn.classList.remove('is-busy')}}
async function api(url,opts={}){const headers={...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opts.headers||{})};if(opts.method&&opts.method!=='GET'&&A.csrf)headers['x-csrf-token']=A.csrf;const r=await fetch(url,{...opts,headers,cache:'no-store'});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function uploadImage(file){if(!file||!file.size)return '';const fd=new FormData();fd.append('file',file);const out=await api('/api/admin/media',{method:'POST',body:fd});return out.url}
async function boot(){try{const me=await api('/api/admin/me');A.user=me;A.csrf=me.csrf;renderShell();await loadView()}catch{renderLogin()}}
function renderLogin(){document.body.innerHTML=`<div class="login-wrap"><div class="login-card"><img class="login-logo" src="/assets/logo.jpg" alt="R TEX BD"><div class="eyebrow" style="margin-top:20px">R TEX BD / ADMIN</div><div class="login-title">Welcome back.</div><p style="color:#777;font-size:13px;margin-bottom:24px">Manage products, orders, reviews and store settings securely.</p><form id="login-form"><div class="field"><label>Admin ID</label><input value="admin" readonly autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn" type="submit" style="width:100%;margin-top:6px">Sign in</button><div id="login-error" style="color:#9c4c4c;font-size:12px;margin-top:10px"></div></form></div></div>`;$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),btn=e.currentTarget.querySelector('button');btn.disabled=true;try{const me=await api('/api/admin/login',{method:'POST',body:JSON.stringify({login_id:'admin',password:fd.get('password')})});A.user=me;A.csrf=me.csrf;renderShell();await loadView()}catch(err){$('#login-error').textContent=err.message;btn.disabled=false}})}
function renderShell(){document.body.innerHTML=`<div class="layout"><div class="sidebar-backdrop" id="sidebar-backdrop" aria-hidden="true"></div><aside class="sidebar" id="sidebar"><div class="side-brand"><div class="side-logo-frame"><img src="/assets/logo.jpg" alt="R TEX BD"></div><span>R TEX BD<br><small>ADMIN</small></span></div><nav class="side-nav">${[['dashboard','Dashboard'],['products','Products'],['categories','Categories'],['orders','Orders'],['landing','Landing page'],['services','Services / highlights'],['faqs','FAQ'],['reviews','Reviews'],['testimonials','Testimonials'],['leads','Leads / messages'],['socials','Social links'],['settings','Settings'],['security','Security']].map(([k,t])=>`<button type="button" data-view="${k}">${t}</button>`).join('')}</nav><div class="side-footer"><button id="logout" class="btn alt" type="button" style="width:100%;border-color:#444;color:#fff;background:transparent">Log out</button><a href="/" target="_blank" rel="noopener" style="display:block;text-align:center;color:#777;font-size:11px;margin-top:12px">Open website ↗</a></div></aside><div class="main"><div class="top"><div class="inline"><button class="btn alt mobile-toggle" type="button" id="toggle-side">☰</button><h1 id="page-title">Dashboard</h1></div><div class="eyebrow">ADMIN</div></div><main class="content" id="view"></main></div></div>`;const closeSidebar=()=>{const side=$('#sidebar');const backdrop=$('#sidebar-backdrop');side?.classList.remove('open');backdrop?.classList.remove('open');backdrop?.setAttribute('aria-hidden','true');document.body.classList.remove('sidebar-locked')};const openSidebar=()=>{const side=$('#sidebar');const backdrop=$('#sidebar-backdrop');side?.classList.add('open');backdrop?.classList.add('open');backdrop?.setAttribute('aria-hidden','false');document.body.classList.add('sidebar-locked')};$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{A.view=b.dataset.view;closeSidebar();loadView()}));$('#toggle-side').addEventListener('click',()=>$('#sidebar').classList.contains('open')?closeSidebar():openSidebar());$('#sidebar-backdrop').addEventListener('click',closeSidebar);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDetailsModal();closeSidebar()}});$('#logout').addEventListener('click',async()=>{try{await api('/api/admin/logout',{method:'POST'});location.reload()}catch(e){toast(e.message,'error')}})}
const titles={dashboard:'Dashboard',products:'Products',categories:'Categories',orders:'Orders',landing:'Landing page',services:'Services / highlights',faqs:'FAQ',reviews:'Reviews',testimonials:'Testimonials',leads:'Leads / messages',socials:'Social links',settings:'Store settings',security:'Security'};
async function loadView(){document.title=`${titles[A.view]} — R TEX BD Admin`;$('#page-title').textContent=titles[A.view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===A.view));$('#view').innerHTML='<div class="view-loading" aria-hidden="true"></div>';try{const loaders={dashboard:loadDashboard,products:loadProducts,categories:loadCategories,orders:loadOrders,landing:loadLanding,services:loadServices,faqs:loadFaqs,reviews:loadReviews,testimonials:loadTestimonials,leads:loadLeads,socials:loadSocials,settings:loadSettings,security:loadSecurity};await loaders[A.view]()}catch(e){$('#view').innerHTML=`<div class="empty">${esc(e.message)}<br><button class="btn" type="button" data-admin-retry>Retry</button></div>`}}
function jump(view){A.view=view;loadView()}
async function loadDashboard(){const d=await api('/api/admin/dashboard');const s=d.stats;$('#view').innerHTML=`<div class="cards"><div class="stat"><div class="label">Orders</div><div class="value">${s.orders}</div></div><div class="stat"><div class="label">Pending</div><div class="value">${s.pending}</div></div><div class="stat"><div class="label">Confirmed</div><div class="value">${s.confirmed}</div></div><div class="stat"><div class="label">Revenue</div><div class="value">৳${Number(s.revenue||0).toLocaleString()}</div></div><div class="stat"><div class="label">Products</div><div class="value">${s.products}</div></div><div class="stat"><div class="label">Reviews</div><div class="value">${s.reviews}</div></div><div class="stat"><div class="label">New leads</div><div class="value">${s.new_leads}</div></div></div><div class="grid2" style="margin-top:18px"><div class="panel"><div class="panel-head"><h2>Recent orders</h2><button class="btn alt mini" type="button" data-jump="orders">View all</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr></thead><tbody>${d.recent_orders.length?d.recent_orders.map(o=>`<tr><td>${esc(o.order_code)}</td><td>${esc(o.customer_name)}</td><td>৳${Number(o.total).toLocaleString()}</td><td><span class="pill">${esc(o.order_status)}</span></td></tr>`).join(''):'<tr><td colspan="4">No orders yet.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Low stock</h2><button class="btn alt mini" type="button" data-jump="products">Products</button></div><div class="item-list">${d.low_stock.length?d.low_stock.map(p=>`<div class="item-card"><div class="item-card-head"><strong>${esc(p.name)}</strong><span class="pill">${p.stock} left</span></div></div>`).join(''):'<div class="empty">No low-stock items.</div>'}</div></div></div>`;$$('[data-jump]').forEach(b=>b.onclick=()=>jump(b.dataset.jump))}
function imageUploadField(name,label,value=''){return `<div class="field full upload-field"><label>${label}</label><div class="upload-row"><input name="${name}" value="${esc(value)}" placeholder="/api/media/123 or https://…"><input type="file" name="${name}_file" accept="image/jpeg,image/png,image/webp"><button class="btn alt mini" type="button" data-upload-target="${name}">Upload</button></div><div class="upload-note" data-preview-for="${name}">${value?`<img class="image-preview mini-preview" src="${esc(value)}" alt="Preview">`:''}</div></div>`}
function productForm(p={}){return `<form class="admin-form" data-form="product" data-id="${p.id||''}"><div class="form-grid"><div class="field"><label>Name *</label><input name="name" value="${esc(p.name||'')}" required></div><div class="field"><label>SKU</label><input name="sku" value="${esc(p.sku||'')}"></div><div class="field"><label>Category</label><select name="category_id"><option value="">— None —</option>${(A.data.categories||[]).map(c=>`<option value="${c.id}" ${Number(p.category_id)===Number(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Sort order</label><input name="sort_order" type="number" value="${Number(p.sort_order||0)}"></div><div class="field"><label>Price *</label><input name="price" type="number" min="0" step="1" value="${p.price??''}" required></div><div class="field"><label>Sale price</label><input name="sale_price" type="number" min="0" step="1" value="${p.sale_price??''}"></div><div class="field"><label>Stock *</label><input name="stock" type="number" min="0" value="${p.stock??0}" required></div>${imageUploadField('image_url','Primary product image *',p.image_url)}<div class="field full"><label>Description</label><textarea name="description">${esc(p.description||'')}</textarea></div><div class="field full"><label>Gallery URLs — one per line</label><textarea name="gallery_text">${esc((p.gallery||[]).join('\n'))}</textarea><input style="margin-top:8px" type="file" name="gallery_files" accept="image/jpeg,image/png,image/webp" multiple></div><div class="field full"><label>Variants JSON</label><textarea name="variants_text" placeholder='[{"name":"Size","options":["S","M","L"]}]'>${esc(JSON.stringify(p.variants||[],null,2))}</textarea></div><div class="inline full"><label><input type="checkbox" name="featured" ${p.featured?'checked':''}> Featured</label><label><input type="checkbox" name="active" ${p.active===0?'':'checked'}> Active</label></div></div><div class="inline" style="margin-top:12px"><button class="btn" type="submit">${p.id?'Save changes':'Add product'}</button><button type="button" class="btn alt" data-cancel-form>Cancel</button></div><div class="form-error" style="color:#9c4c4c;font-size:12px;margin-top:8px"></div></form>`}
async function loadProducts(){A.data.categories=await api('/api/admin/categories');A.data.products=await api('/api/admin/products');$('#view').innerHTML=`<div class="grid2"><div class="panel"><div class="panel-head"><h2>${A.data.products.length} products</h2><button class="btn" type="button" data-new-product>Add product</button></div><div class="item-list">${A.data.products.map(p=>`<div class="item-card product-admin"><div class="admin-product-main"><img src="${esc(p.image_url||'/assets/logo.jpg')}" alt="${esc(p.name)}"><div><strong>${esc(p.name)}</strong><div class="muted">${esc(p.category_name||'Uncategorized')} · ৳${Number(p.sale_price??p.price).toLocaleString()} · ${p.stock} stock</div><span class="pill">${p.active?'Active':'Hidden'}</span></div></div><div class="row-actions"><button class="btn alt mini" type="button" data-product-edit="${p.id}">Edit</button><button class="btn alt mini" type="button" data-product-details="${p.id}">View details</button>${p.active?`<button class="btn alt mini" type="button" data-product-hide="${p.id}">Hide</button>`:`<button class="btn alt mini" type="button" data-product-restore="${p.id}">Restore</button>`}<button class="btn alt mini danger" type="button" data-product-delete="${p.id}">Delete</button></div></div>`).join('')||'<div class="empty">No products.</div>'}</div></div><div class="panel"><div id="product-editor" class="empty">Select Add or Edit.</div></div></div>`;$('#view').onclick=async e=>{const n=e.target.closest('[data-new-product]');const ed=e.target.closest('[data-product-edit]');const det=e.target.closest('[data-product-details]');const hide=e.target.closest('[data-product-hide]');const restore=e.target.closest('[data-product-restore]');const del=e.target.closest('[data-product-delete]');if(n){$('#product-editor').innerHTML=productForm();wireProductForm();return}if(ed){$('#product-editor').innerHTML=productForm(A.data.products.find(x=>Number(x.id)===Number(ed.dataset.productEdit))||{});wireProductForm();return}if(det){const p=A.data.products.find(x=>Number(x.id)===Number(det.dataset.productDetails));openDetailsModal('Product details',`<div class="detail-grid"><img class="detail-image" src="${esc(p.image_url||'/assets/logo.jpg')}" alt="${esc(p.name)}"><div><div class="eyebrow">${esc(p.category_name||'Collection')}</div><h2>${esc(p.name)}</h2><p>${esc(p.description||'No description')}</p><div class="price">৳${Number(p.sale_price??p.price).toLocaleString()} ${p.sale_price!=null?`<span class="compare">৳${Number(p.price).toLocaleString()}</span>`:''}</div><p class="muted">Stock: ${p.stock} · SKU: ${esc(p.sku||'—')}</p></div></div>`);return}if(hide){return runAction(hide,async()=>{await api('/api/admin/products/'+hide.dataset.productHide,{method:'DELETE'});toast('Product hidden','success');await loadView()})}if(restore){return runAction(restore,async()=>{await api('/api/admin/products/'+restore.dataset.productRestore,{method:'PUT',body:JSON.stringify({...A.data.products.find(x=>Number(x.id)===Number(restore.dataset.productRestore)),active:true})});toast('Product restored','success');await loadView()})}if(del&&confirm('Permanently delete this product?')){return runAction(del,async()=>{await api('/api/admin/products/'+del.dataset.productDelete+'/permanent',{method:'DELETE'});toast('Product deleted','success');await loadView()})}};wireProductUploads()}
function wireProductUploads(){document.querySelectorAll('[data-upload-target]').forEach(b=>b.addEventListener('click',async()=>{const target=b.dataset.uploadTarget,input=document.querySelector(`[name="${target}_file"]`);if(!input?.files[0])return toast('Choose an image first','error');try{b.disabled=true;const url=await uploadImage(input.files[0]);document.querySelector(`[name="${target}"]`).value=url;document.querySelector(`[data-preview-for="${target}"]`).innerHTML=`<img class="image-preview mini-preview" src="${esc(url)}" alt="Preview">`;toast('Image uploaded','success')}catch(e){toast(e.message,'error')}finally{b.disabled=false}}))}
function wireProductForm(){const form=$('.admin-form');form.querySelector('[data-cancel-form]').onclick=()=>{$('#product-editor').innerHTML='<div class="empty">Select Add or Edit.</div>'};form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button[type="submit"]'),fd=new FormData(form);btn.disabled=true;try{let image=fd.get('image_url');if(fd.get('image_url_file')?.size)image=await uploadImage(fd.get('image_url_file'));let gallery=(String(fd.get('gallery_text')||'').split(/\n+/).map(x=>x.trim()).filter(Boolean));for(const file of [...(fd.getAll('gallery_files')||[])])if(file?.size)gallery.push(await uploadImage(file));let variants=[];try{variants=JSON.parse(String(fd.get('variants_text')||'[]'))}catch{throw new Error('Variants JSON is invalid.')}const payload={name:fd.get('name'),sku:fd.get('sku'),category_id:fd.get('category_id'),sort_order:fd.get('sort_order'),price:fd.get('price'),sale_price:fd.get('sale_price'),stock:fd.get('stock'),image_url:image,description:fd.get('description'),gallery,variants,featured:fd.has('featured'),active:fd.has('active')};const id=form.dataset.id;if(id)await api('/api/admin/products/'+id,{method:'PUT',body:JSON.stringify(payload)});else await api('/api/admin/products',{method:'POST',body:JSON.stringify(payload)});toast('Product saved','success');await loadProducts()}catch(x){form.querySelector('.form-error').textContent=x.message}finally{btn.disabled=false}};wireProductUploads()}
function categoryForm(c={}){return `<form class="generic-form" data-id="${c.id||''}"><div class="field"><label>Name *</label><input name="name" value="${esc(c.name||'')}" required></div><div class="field"><label>Description</label><textarea name="description">${esc(c.description||'')}</textarea></div>${imageUploadField('image_url','Category image',c.image_url)}<div class="inline"><label><input type="checkbox" name="active" ${c.active===0?'':'checked'}> Active</label><label>Order <input name="sort_order" type="number" value="${c.sort_order||0}" style="width:90px"></label></div><button class="btn" type="submit" style="margin-top:12px">Save category</button></form>`}
async function loadCategories(){const xs=await api('/api/admin/categories');$('#view').innerHTML=`<div class="grid2"><div class="panel"><div class="panel-head"><h2>Categories</h2><button class="btn" type="button" data-category-add>Add</button></div><div class="item-list">${xs.map(x=>`<div class="item-card"><div class="item-card-head"><strong>${esc(x.name)}</strong><span class="pill">${x.active?'Active':'Hidden'}</span></div><div class="row-actions"><button class="btn alt mini" type="button" data-category-edit="${x.id}">Edit</button><button class="btn alt mini danger" type="button" data-category-delete="${x.id}">Delete</button></div></div>`).join('')||'<div class="empty">No categories.</div>'}</div></div><div class="panel"><div id="category-editor" class="empty">Select Add or Edit.</div></div></div>`;$('#view').onclick=async e=>{const add=e.target.closest('[data-category-add]'),ed=e.target.closest('[data-category-edit]'),del=e.target.closest('[data-category-delete]');if(add){$('#category-editor').innerHTML=categoryForm();wireCategoryForm();}if(ed){$('#category-editor').innerHTML=categoryForm(xs.find(x=>Number(x.id)===Number(ed.dataset.categoryEdit))||{});wireCategoryForm()}if(del&&confirm('Delete category?')){return runAction(del,async()=>{await api('/api/admin/categories/'+del.dataset.categoryDelete,{method:'DELETE'});toast('Category deleted','success');await loadView()})}}}
function wireCategoryForm(){const f=$('.generic-form');wireUploadFields(f);f.onsubmit=async e=>{e.preventDefault();const fd=new FormData(f);let image=fd.get('image_url');if(fd.get('image_url_file')?.size)image=await uploadImage(fd.get('image_url_file'));const p={name:fd.get('name'),description:fd.get('description'),image_url:image,active:fd.has('active'),sort_order:fd.get('sort_order')};const id=f.dataset.id;if(id)await api('/api/admin/categories/'+id,{method:'PUT',body:JSON.stringify(p)});else await api('/api/admin/categories',{method:'POST',body:JSON.stringify(p)});toast('Category saved','success');loadView()}}
function wireUploadFields(root=document){root.querySelectorAll('[data-upload-target]').forEach(b=>b.addEventListener('click',async()=>{const target=b.dataset.uploadTarget,input=root.querySelector(`[name="${target}_file"]`);if(!input?.files[0])return toast('Choose an image first','error');try{b.disabled=true;const url=await uploadImage(input.files[0]);root.querySelector(`[name="${target}"]`).value=url;root.querySelector(`[data-preview-for="${target}"]`).innerHTML=`<img class="image-preview mini-preview" src="${esc(url)}" alt="Preview">`;toast('Image uploaded','success')}catch(e){toast(e.message,'error')}finally{b.disabled=false}}))}
function serviceForm(x={}){return `<form class="generic-form" data-id="${x.id||''}"><div class="field"><label>Title *</label><input name="title" value="${esc(x.title||'')}" required></div><div class="field"><label>Description</label><textarea name="description">${esc(x.description||'')}</textarea></div>${imageUploadField('image_url','Image',x.image_url)}<div class="field"><label>Icon / short label</label><input name="icon" value="${esc(x.icon||'')}"></div><div class="field"><label>Price</label><input name="price" type="number" min="0" value="${x.price??''}"></div><div class="field"><label>Button text</label><input name="button_text" value="${esc(x.button_text||'')}"></div><div class="field"><label>Button action URL</label><input name="button_action" value="${esc(x.button_action||'')}"></div><div class="inline"><label><input type="checkbox" name="enabled" ${x.enabled===0?'':'checked'}> Enabled</label><label>Order <input name="sort_order" type="number" value="${x.sort_order||0}" style="width:90px"></label></div><button class="btn" type="submit" style="margin-top:12px">Save</button></form>`}
function faqForm(x={}){return `<form class="generic-form" data-id="${x.id||''}"><div class="field"><label>Question *</label><input name="question" value="${esc(x.question||'')}" required></div><div class="field"><label>Answer *</label><textarea name="answer" required>${esc(x.answer||'')}</textarea></div><div class="inline"><label><input type="checkbox" name="enabled" ${x.enabled===0?'':'checked'}> Enabled</label><label>Order <input name="sort_order" type="number" value="${x.sort_order||0}" style="width:90px"></label></div><button class="btn" type="submit" style="margin-top:12px">Save</button></form>`}
function reviewForm(x={}){return `<form class="generic-form" data-id="${x.id||''}"><div class="field"><label>Customer name *</label><input name="customer_name" value="${esc(x.customer_name||'')}" required></div><div class="field"><label>Rating (1–5) *</label><input name="rating" type="number" min="1" max="5" value="${x.rating||5}" required></div><div class="field full"><label>Review text *</label><textarea name="quote" required>${esc(x.quote||'')}</textarea></div>${imageUploadField('image_url','Review screenshot / photo',x.image_url)}<div class="inline"><label><input type="checkbox" name="enabled" ${x.enabled===0?'':'checked'}> Enabled</label><label>Order <input name="sort_order" type="number" value="${x.sort_order||0}" style="width:90px"></label></div><button class="btn" type="submit" style="margin-top:12px">Save review</button></form>`}
function testimonialForm(x={}){return `<form class="generic-form" data-id="${x.id||''}"><div class="field"><label>Name *</label><input name="name" value="${esc(x.name||'')}" required></div><div class="field"><label>Role</label><input name="role" value="${esc(x.role||'')}"></div><div class="field"><label>Quote *</label><textarea name="quote" required>${esc(x.quote||'')}</textarea></div>${imageUploadField('avatar_url','Avatar',x.avatar_url)}<div class="inline"><label><input type="checkbox" name="enabled" ${x.enabled===0?'':'checked'}> Enabled</label><label>Order <input name="sort_order" type="number" value="${x.sort_order||0}" style="width:90px"></label></div><button class="btn" type="submit" style="margin-top:12px">Save</button></form>`}
function socialForm(x={}){return `<form class="generic-form" data-id="${x.id||''}"><div class="field"><label>Platform *</label><input name="platform" value="${esc(x.platform||'')}" placeholder="Facebook / Instagram / TikTok / Website" required></div><div class="field"><label>Label</label><input name="label" value="${esc(x.label||'')}"></div><div class="field full"><label>URL *</label><input name="url" type="url" value="${esc(x.url||'')}" required></div>${imageUploadField('icon_url','Icon image (optional)',x.icon_url)}<div class="inline"><label><input type="checkbox" name="enabled" ${x.enabled===0?'':'checked'}> Enabled</label><label>Order <input name="sort_order" type="number" value="${x.sort_order||0}" style="width:90px"></label></div><button class="btn" type="submit" style="margin-top:12px">Save</button></form>`}
async function loadCategoriesUnused(){}
function renderCrud(title,type,items,summary,form){return `<div class="grid2"><div class="panel"><div class="panel-head"><h2>${title}</h2><button class="btn" type="button" data-simple-add="${type}">Add</button></div><div class="item-list">${items.map(x=>`<div class="item-card"><div class="item-card-head">${summary(x)}<div class="row-actions"><button class="btn alt mini" type="button" data-simple-edit="${type}" data-id="${x.id}">Edit</button><button class="btn alt mini danger" type="button" data-simple-delete="${type}" data-id="${x.id}">Delete</button></div></div></div>`).join('')||'<div class="empty">No records yet.</div>'}</div></div><div class="panel"><div id="simple-editor" class="empty">Select Add or Edit.</div></div></div>`}
function wireSimpleCrud(type,items){const map={service:{api:'/api/admin/services',form:serviceForm,load:loadServices},faq:{api:'/api/admin/faqs',form:faqForm,load:loadFaqs},review:{api:'/api/admin/reviews',form:reviewForm,load:loadReviews},testimonial:{api:'/api/admin/testimonials',form:testimonialForm,load:loadTestimonials},social:{api:'/api/admin/socials',form:socialForm,load:loadSocials}}[type];$('#view').onclick=async e=>{const add=e.target.closest('[data-simple-add]'),edit=e.target.closest('[data-simple-edit]'),del=e.target.closest('[data-simple-delete]');if(add||edit){const x=edit?items.find(i=>Number(i.id)===Number(edit.dataset.id)):{};$('#simple-editor').innerHTML=map.form(x);wireUploadFields($('#simple-editor'));$('#simple-editor .generic-form').onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget);let payload=Object.fromEntries(fd.entries());for(const k of ['enabled'])payload[k]=fd.has(k);for(const field of ['image_url','avatar_url','icon_url']){const file=fd.get(field+'_file');if(file?.size)payload[field]=await uploadImage(file)}try{if(ev.currentTarget.dataset.id)await api(map.api+'/'+ev.currentTarget.dataset.id,{method:'PUT',body:JSON.stringify(payload)});else await api(map.api,{method:'POST',body:JSON.stringify(payload)});toast('Saved','success');await map.load()}catch(err){toast(err.message,'error')}}}if(del&&confirm('Delete this item?')){try{await api(map.api+'/'+del.dataset.id,{method:'DELETE'});toast('Deleted','success');await map.load()}catch(err){toast(err.message,'error')}}}}
async function loadServices(){const xs=await api('/api/admin/services');$('#view').innerHTML=renderCrud('Services / highlights','service',xs,x=>`<div><strong>${esc(x.title)}</strong><div class="muted">${esc(x.description||'')}</div></div>`,serviceForm);wireSimpleCrud('service',xs)}
async function loadFaqs(){const xs=await api('/api/admin/faqs');$('#view').innerHTML=renderCrud('FAQ','faq',xs,x=>`<div><strong>${esc(x.question)}</strong><div class="muted">${esc(x.answer.slice(0,160))}</div></div>`,faqForm);wireSimpleCrud('faq',xs)}
async function loadReviews(){const xs=await api('/api/admin/reviews');$('#view').innerHTML=renderCrud('Customer Reviews','review',xs,x=>`<div class="review-admin-row">${x.image_url?`<img src="${esc(x.image_url)}" alt="">`:''}<div><strong>${esc(x.customer_name)}</strong><div class="stars">${'★'.repeat(Number(x.rating)||5)}</div><div class="muted">${esc(x.quote.slice(0,140))}</div></div></div>`,reviewForm);wireSimpleCrud('review',xs)}
async function loadTestimonials(){const xs=await api('/api/admin/testimonials');$('#view').innerHTML=renderCrud('Testimonials','testimonial',xs,x=>`<div><strong>${esc(x.name)}</strong><div class="muted">${esc(x.quote.slice(0,140))}</div></div>`,testimonialForm);wireSimpleCrud('testimonial',xs)}
async function loadSocials(){const xs=await api('/api/admin/socials');$('#view').innerHTML=renderCrud('Social links','social',xs,x=>`<div><strong>${esc(x.label)}</strong><div class="muted">${esc(x.url)}</div></div>`,socialForm);wireSimpleCrud('social',xs)}
function landingForm(x={}){const c=x.content||{};const items=Array.isArray(c.items)?c.items:[];return `<form class="generic-form" data-id="${x.id||''}"><div class="form-grid"><div class="field"><label>Section name</label><input name="section_key" value="${esc(x.section_key||'')}" ${x.id?'readonly':''} required></div><div class="field"><label>Section type</label><select name="type">${['hero','categories','products','story','about','benefits','services','faq','reviews','testimonials','contact','promo','banner','marquee'].map(t=>`<option ${x.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Title</label><input name="title" value="${esc(x.title||'')}"></div><div class="field"><label>Subtitle / small heading</label><input name="subtitle" value="${esc(x.subtitle||'')}"></div><div class="field full"><label>Description / body</label><textarea name="body">${esc(x.body||'')}</textarea></div>${imageUploadField('image_url','Section image',x.image_url)}<div class="field"><label>Button text</label><input name="button_text" value="${esc(x.button_text||'')}" placeholder="Shop now"></div><div class="field"><label>Button link</label><input name="button_url" value="${esc(x.button_url||'')}" placeholder="/shop or https://…"></div><div class="field"><label>Hero secondary text</label><input name="secondary_text" value="${esc(c.secondary_text||'')}" placeholder="Optional supporting line"></div><div class="field"><label>Product section limit</label><input name="product_limit" type="number" min="1" max="24" value="${Number(c.limit||8)}"></div><div class="field"><label><input type="checkbox" name="featured_only" ${c.featured_only?'checked':''}> Products: featured only</label></div></div><div class="builder-subpanel" style="margin-top:16px"><div class="panel-head"><div><h3 style="margin:0">Benefit cards (for Benefits section)</h3><p class="muted">Add/edit cards without touching JSON.</p></div><button type="button" class="btn alt mini" data-add-benefit>Add card</button></div><div id="benefit-builder">${items.map((it,i)=>`<div class="item-card benefit-row" data-benefit-row><div class="form-grid"><div class="field"><label>Number</label><input data-b-num value="${esc(it.eyebrow||'0'+(i+1))}"></div><div class="field"><label>Card title</label><input data-b-title value="${esc(it.title||'')}"></div><div class="field full"><label>Card text</label><textarea data-b-body>${esc(it.body||'')}</textarea></div><div class="inline"><button type="button" class="btn alt mini danger" data-remove-benefit>Remove card</button></div></div></div>`).join('')}</div></div><details style="margin-top:16px"><summary>Advanced section data (optional)</summary><p class="muted">Only use this if you need a custom supported value. Normal editing does not require it.</p><textarea name="advanced_content" style="width:100%;min-height:120px">${esc(JSON.stringify(c,null,2))}</textarea></details><div class="inline" style="margin-top:14px"><label><input type="checkbox" name="enabled" ${x.enabled===0?'':'checked'}> Visible on website</label><label>Display order <input name="sort_order" type="number" value="${x.sort_order||0}" style="width:90px"></label></div><button class="btn" type="submit" style="margin-top:12px">Save section</button></form>`}
async function loadLanding(){const xs=await api('/api/admin/landing');$('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>Landing page sections</h2><button class="btn" type="button" data-landing-add>Add section</button></div><div class="landing-list">${xs.map(x=>`<div class="item-card"><div class="item-card-head"><div><strong>${esc(x.title||x.section_key)}</strong><div class="muted">${esc(x.type)} · order ${x.sort_order}</div></div><span class="pill">${x.enabled?'Visible':'Hidden'}</span></div><div class="row-actions"><button class="btn alt mini" type="button" data-landing-edit="${x.id}">Edit</button><button class="btn alt mini danger" type="button" data-landing-delete="${x.id}">Delete</button></div></div>`).join('')}</div></div><div id="landing-editor"></div>`;$('#view').onclick=async e=>{const add=e.target.closest('[data-landing-add]'),ed=e.target.closest('[data-landing-edit]'),del=e.target.closest('[data-landing-delete]');if(add){$('#landing-editor').innerHTML='<div class="panel">'+landingForm({type:'promo',enabled:1})+'</div>';wireLandingForm();}if(ed){const x=xs.find(i=>Number(i.id)===Number(ed.dataset.landingEdit));$('#landing-editor').innerHTML='<div class="panel">'+landingForm(x)+'</div>';wireLandingForm()}if(del&&confirm('Delete section?')){return runAction(del,async()=>{await api('/api/admin/landing/'+del.dataset.landingDelete,{method:'DELETE'});toast('Section deleted','success');await loadView()})}}}
function wireLandingForm(){const f=$('.generic-form');wireUploadFields(f);const benefitRow=(it={},i=0)=>`<div class="item-card benefit-row" data-benefit-row><div class="form-grid"><div class="field"><label>Number</label><input data-b-num value="${esc(it.eyebrow||'0'+(i+1))}"></div><div class="field"><label>Card title</label><input data-b-title value="${esc(it.title||'')}"></div><div class="field full"><label>Card text</label><textarea data-b-body>${esc(it.body||'')}</textarea></div><div class="inline"><button type="button" class="btn alt mini danger" data-remove-benefit>Remove card</button></div></div></div>`;f.querySelector('[data-add-benefit]')?.addEventListener('click',()=>{const box=f.querySelector('#benefit-builder');box.insertAdjacentHTML('beforeend',benefitRow({},box.children.length))});f.querySelector('#benefit-builder')?.addEventListener('click',e=>{if(e.target.closest('[data-remove-benefit]'))e.target.closest('[data-benefit-row]')?.remove()});f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('button[type=submit]');return runAction(btn,async()=>{const fd=new FormData(f);let advanced={};try{advanced=JSON.parse(String(fd.get('advanced_content')||'{}'))}catch{advanced={}}const benefits=[...f.querySelectorAll('[data-benefit-row]')].map((r,i)=>({eyebrow:r.querySelector('[data-b-num]')?.value||String(i+1).padStart(2,'0'),title:r.querySelector('[data-b-title]')?.value||'',body:r.querySelector('[data-b-body]')?.value||''})).filter(x=>x.title||x.body);let content={...advanced,secondary_text:fd.get('secondary_text')||'',limit:Math.max(1,Math.min(24,Number(fd.get('product_limit')||8))),featured_only:fd.has('featured_only')};if(benefits.length)content.items=benefits;let image=fd.get('image_url');if(fd.get('image_url_file')?.size)image=await uploadImage(fd.get('image_url_file'));const payload={section_key:fd.get('section_key'),type:fd.get('type'),title:fd.get('title'),subtitle:fd.get('subtitle'),body:fd.get('body'),image_url:image,button_text:fd.get('button_text'),button_url:fd.get('button_url'),content,enabled:fd.has('enabled'),sort_order:fd.get('sort_order')};if(f.dataset.id)await api('/api/admin/landing/'+f.dataset.id,{method:'PUT',body:JSON.stringify(payload)});else await api('/api/admin/landing',{method:'POST',body:JSON.stringify(payload)});toast('Section saved','success');await loadView()})}}
async function loadOrders(){
 const status=new URLSearchParams(location.search).get('status')||'';
 const xs=await api('/api/admin/orders'+(status?'?status='+encodeURIComponent(status):''));
 $('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>Orders</h2><div class="inline"><select id="order-status-filter"><option value="">All</option>${['pending','confirmed','processing','shipped','delivered','cancelled'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>${xs.map(o=>`<tr><td>${esc(o.created_at)}</td><td>${esc(o.order_code)}</td><td>${esc(o.customer_name)}<br>${esc(o.phone)}</td><td>৳${Number(o.total).toLocaleString()}</td><td>${esc(o.payment_method)}<br><span class="pill">${esc(o.payment_status)}</span></td><td><span class="pill">${esc(o.order_status)}</span></td><td><button class="btn alt mini" type="button" data-order-details="${o.id}">View</button></td></tr>`).join('')||'<tr><td colspan="7">No orders found.</td></tr>'}</tbody></table></div></div>`;
 $('#order-status-filter').onchange=()=>{const v=$('#order-status-filter').value;location.search=v?'?status='+encodeURIComponent(v):''};
 $$('[data-order-details]').forEach(b=>b.onclick=async()=>runAction(b,async()=>{
   const o=await api('/api/admin/orders/'+b.dataset.orderDetails);
   openDetailsModal('Order '+o.order_code,`<div><h3>${esc(o.customer_name)}</h3><p>${esc(o.phone)} · ${esc(o.email||'')}</p><p>${esc(o.address)}, ${esc(o.city||'')}</p><div class="order-items">${o.items.map(i=>`<div class="checkout-item"><div>${esc(i.product_name)}${i.variant?` · ${esc(i.variant)}`:''} × ${i.quantity}</div><strong>৳${Number(i.line_total).toLocaleString()}</strong></div>`).join('')}</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Order status</label><select id="modal-order-status">${['pending','confirmed','processing','shipped','delivered','cancelled'].map(s=>`<option ${s===o.order_status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Payment status</label><select id="modal-payment-status">${['pending','paid','failed','refunded'].map(s=>`<option ${s===o.payment_status?'selected':''}>${s}</option>`).join('')}</select></div><div class="field full"><label>Internal note</label><textarea id="modal-internal-note">${esc(o.internal_note||'')}</textarea></div></div><button class="btn" type="button" id="save-order-status" style="margin-top:12px">Save order</button></div>`);
   $('#save-order-status').onclick=()=>runAction($('#save-order-status'),async()=>{
     await api('/api/admin/orders/'+o.id,{method:'PUT',body:JSON.stringify({order_status:$('#modal-order-status').value,payment_status:$('#modal-payment-status').value,internal_note:$('#modal-internal-note').value})});
     toast('Order updated','success');closeDetailsModal();await loadView();
   });
 }));
}
async function loadLeads(){const xs=await api('/api/admin/leads');$('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>Leads & messages</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Name</th><th>Contact</th><th>Interest</th><th>Message</th><th>Status</th><th></th></tr></thead><tbody>${xs.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.name)}</td><td>${esc(x.phone)}<br>${esc(x.email)}</td><td>${esc(x.interest)}</td><td>${esc(x.message)}</td><td><select data-lead-status="${x.id}">${['new','contacted','resolved','archived'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="btn alt mini danger" type="button" data-lead-delete="${x.id}">Delete</button></td></tr>`).join('')||'<tr><td colspan="7">No leads yet.</td></tr>'}</tbody></table></div></div>`;$$('[data-lead-status]').forEach(s=>s.onchange=async()=>{try{await api('/api/admin/leads/'+s.dataset.leadStatus,{method:'PUT',body:JSON.stringify({status:s.value})});toast('Lead updated','success')}catch(e){toast(e.message,'error')}});$$('[data-lead-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete lead?'))return runAction(b,async()=>{await api('/api/admin/leads/'+b.dataset.leadDelete,{method:'DELETE'});await loadView()})})}
async function loadSettings(){
 const s=await api('/api/admin/settings');
 const header=(()=>{try{const x=JSON.parse(s.header_items||'[]');return x.length?x:[{label:'Home',href:'/',enabled:true,order:0},{label:'Shop',href:'/shop',enabled:true,order:1},{label:'About',href:'/about',enabled:true,order:2},{label:'Contact',href:'/contact',enabled:true,order:3},{label:'Track order',href:'/track',enabled:true,order:4}]}catch{return[]}})();
 const footer=(()=>{try{const x=JSON.parse(s.footer_columns||'[]');return x.length?x:[{title:'Navigate',links:[{label:'Shop',href:'/shop',enabled:true},{label:'About',href:'/about',enabled:true},{label:'Contact',href:'/contact',enabled:true},{label:'Track order',href:'/track',enabled:true}],enabled:true,order:0},{title:'Connect',body:'Add your contact details here.',links:[],enabled:true,order:1}]}catch{return[]}})();
 const theme=(()=>{try{return JSON.parse(s.theme_config||'{}')}catch{return{}}})();
 const baseKeys=['store_name','tagline','phone','whatsapp','email','address','support_hours','delivery_fee','delivery_note','about_store','bkash_enabled','bkash_number','nagad_enabled','nagad_number','rocket_enabled','rocket_number','cod_enabled','payment_note','seo_title','seo_description','seo_keywords','footer_copyright'];
 const textareas=['about_store','payment_note','seo_description','footer_copyright'];
 const headerRow=(x={},i=0)=>`<div class="item-card builder-row" data-header-row><div class="form-grid"><div class="field"><label>Label / text</label><input data-h-label value="${esc(x.label||'')}" placeholder="WhatsApp"></div><div class="field"><label>Value (optional)</label><input data-h-value value="${esc(x.value||'')}" placeholder="017XXXXXXXX"></div><div class="field"><label>Link / action</label><input data-h-href value="${esc(x.href||'')}" placeholder="https://wa.me/... or tel:+880..."></div><div class="field full"><label>Icon image (optional)</label><div class="upload-row"><input data-h-icon-url value="${esc(x.icon_url||'')}" placeholder="/api/media/123 or https://…"><input data-h-icon-file type="file" accept="image/jpeg,image/png,image/webp"><button type="button" class="btn alt mini" data-upload-header-icon>Upload</button></div><div class="upload-note">${x.icon_url?`<img class="image-preview mini-preview" src="${esc(x.icon_url)}" alt="Preview">`:''}</div></div><div class="field"><label>Text icon (optional)</label><input data-h-icon value="${esc(x.icon||'')}" placeholder="☎ / ✓ / etc."></div><div class="inline"><label><input type="checkbox" data-h-enabled ${x.enabled===false?'':'checked'}> Show</label><label>Order <input data-h-order type="number" value="${Number(x.order??i)}" style="width:90px"></label><button type="button" class="btn alt mini danger" data-remove-header>Remove</button></div></div></div>`;
 const footerRow=(x={},i=0)=>`<div class="item-card builder-row" data-footer-row><div class="form-grid"><div class="field"><label>Column title</label><input data-f-title value="${esc(x.title||'')}" placeholder="Customer care"></div><div class="field full"><label>Column text (optional)</label><textarea data-f-body>${esc(x.body||'')}</textarea></div><div class="field full"><label>Links (one per line: Label | URL)</label><textarea data-f-links>${(Array.isArray(x.links)?x.links.map(l=>`${l.label||l.text||''} | ${l.href||l.url||''}`).join('\n'):'')}</textarea></div><div class="inline"><label><input type="checkbox" data-f-enabled ${x.enabled===false?'':'checked'}> Show</label><label>Order <input data-f-order type="number" value="${Number(x.order??i)}" style="width:90px"></label><button type="button" class="btn alt mini danger" data-remove-footer>Remove</button></div></div></div>`;
 $('#view').innerHTML=`<div class="panel"><div class="panel-head"><div><h2>Store identity & contact</h2><p class="muted">Change website content without editing code.</p></div></div><form id="identity-form"><div class="form-grid" style="margin-top:16px">${imageUploadField('logo_url','Logo',s.logo_url)}${imageUploadField('favicon_url','Browser icon',s.favicon_url)}${baseKeys.map(k=>`<div class="field ${textareas.includes(k)?'full':''}"><label>${esc(k.replaceAll('_',' '))}</label>${textareas.includes(k)?`<textarea name="${k}">${esc(s[k]||'')}</textarea>`:`<input name="${k}" value="${esc(s[k]||'')}">`}</div>`).join('')}${imageUploadField('og_image','Social sharing image',s.og_image)}</div><button class="btn" type="submit" style="margin-top:12px">Save store settings</button></form></div>
 <div class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Header builder</h2><p class="muted">Add phone, WhatsApp, custom links and icons. No coding required.</p></div><button type="button" class="btn alt" id="add-header-item">Add header item</button></div><div id="header-builder" class="builder-list">${header.map(headerRow).join('')}</div><button class="btn" type="button" id="save-header" style="margin-top:12px">Save header</button></div>
 <div class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Footer builder</h2><p class="muted">Create footer columns and links visually.</p></div><button type="button" class="btn alt" id="add-footer-column">Add footer column</button></div><div id="footer-builder" class="builder-list">${footer.map(footerRow).join('')}</div><button class="btn" type="button" id="save-footer" style="margin-top:12px">Save footer</button></div>
 <div class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Visual theme</h2><p class="muted">Change colors, spacing and shape without CSS/code.</p></div></div><form id="theme-form" class="form-grid"><div class="field"><label>Page background</label><input name="bg" type="color" value="${/^#[0-9a-f]{6}$/i.test(theme.bg)?theme.bg:'#f6f4ef'}"></div><div class="field"><label>Text color</label><input name="text" type="color" value="${/^#[0-9a-f]{6}$/i.test(theme.text)?theme.text:'#171717'}"></div><div class="field"><label>Accent color</label><input name="accent" type="color" value="${/^#[0-9a-f]{6}$/i.test(theme.accent)?theme.accent:'#171717'}"></div><div class="field"><label>Button color</label><input name="button" type="color" value="${/^#[0-9a-f]{6}$/i.test(theme.button)?theme.button:'#171717'}"></div><div class="field"><label>Card radius (px)</label><input name="radius" type="number" min="0" max="40" value="${esc(theme.radius||'18')}"></div><div class="field"><label>Container width (px)</label><input name="container_max" type="number" min="900" max="1800" value="${esc(theme.container_max||'1240')}"></div><button class="btn full" type="submit">Save visual theme</button></form></div>
 <div class="panel" style="margin-top:18px"><div class="panel-head"><div><h2>Media library</h2><p class="muted">Upload JPG, PNG or WebP up to 2 MB, then use the image in any supported editor.</p></div></div><form id="upload-form"><div class="field"><label>Choose image</label><input name="file" type="file" accept="image/jpeg,image/png,image/webp" required></div><button class="btn" type="submit">Upload image</button><div id="upload-result" style="margin-top:12px"></div></form></div>`;
 wireUploadFields($('#identity-form'));
 document.querySelectorAll('[data-upload-header-icon]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-header-row]');const file=row?.querySelector('[data-h-icon-file]')?.files?.[0];if(!file)return toast('Choose an icon image first','error');await runAction(btn,async()=>{const url=await uploadImage(file);row.querySelector('[data-h-icon-url]').value=url;row.querySelector('.upload-note').innerHTML=`<img class="image-preview mini-preview" src="${esc(url)}" alt="Preview">`;toast('Header icon uploaded','success')})});
 $('#identity-form').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button[type=submit]');await runAction(btn,async()=>{const fd=new FormData(e.currentTarget);await api('/api/admin/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(fd.entries()))});toast('Store settings saved','success')})};
 $('#add-header-item').onclick=()=>{const box=$('#header-builder');box.insertAdjacentHTML('beforeend',headerRow({},box.children.length));box.querySelectorAll('[data-upload-header-icon]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-header-row]');const file=row?.querySelector('[data-h-icon-file]')?.files?.[0];if(!file)return toast('Choose an icon image first','error');await runAction(btn,async()=>{const url=await uploadImage(file);row.querySelector('[data-h-icon-url]').value=url;row.querySelector('.upload-note').innerHTML=`<img class="image-preview mini-preview" src="${esc(url)}" alt="Preview">`;toast('Header icon uploaded','success')})});};
 $('#header-builder').onclick=e=>{const r=e.target.closest('[data-remove-header]');if(r)r.closest('[data-header-row]')?.remove()};
 $('#save-header').onclick=()=>runAction($('#save-header'),async()=>{const items=[...document.querySelectorAll('[data-header-row]')].map((r,i)=>({label:r.querySelector('[data-h-label]')?.value||'',value:r.querySelector('[data-h-value]')?.value||'',href:r.querySelector('[data-h-href]')?.value||'',icon_url:r.querySelector('[data-h-icon-url]')?.value||'',icon:r.querySelector('[data-h-icon]')?.value||'',enabled:!!r.querySelector('[data-h-enabled]')?.checked,order:Number(r.querySelector('[data-h-order]')?.value||i)})).filter(x=>x.label||x.value||x.href||x.icon_url||x.icon);await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({header_items:JSON.stringify(items)})});toast('Header saved','success')});
 $('#add-footer-column').onclick=()=>{const box=$('#footer-builder');box.insertAdjacentHTML('beforeend',footerRow({},box.children.length));};
 $('#footer-builder').onclick=e=>{const r=e.target.closest('[data-remove-footer]');if(r)r.closest('[data-footer-row]')?.remove()};
 $('#save-footer').onclick=()=>runAction($('#save-footer'),async()=>{const cols=[...document.querySelectorAll('[data-footer-row]')].map((r,i)=>({title:r.querySelector('[data-f-title]')?.value||'',body:r.querySelector('[data-f-body]')?.value||'',links:String(r.querySelector('[data-f-links]')?.value||'').split(/\n/).map(line=>{const [label,...rest]=line.split('|');return {label:String(label||'').trim(),href:rest.join('|').trim(),enabled:true}}).filter(x=>x.label&&x.href),enabled:!!r.querySelector('[data-f-enabled]')?.checked,order:Number(r.querySelector('[data-f-order]')?.value||i)})).filter(x=>x.title||x.body||x.links.length);await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({footer_columns:JSON.stringify(cols)})});toast('Footer saved','success')});
 $('#theme-form').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('button[type=submit]');await runAction(btn,async()=>{const fd=new FormData(e.currentTarget);const theme={bg:fd.get('bg'),text:fd.get('text'),accent:fd.get('accent'),button:fd.get('button'),radius:String(Math.max(0,Math.min(40,Number(fd.get('radius')||18)))),container_max:String(Math.max(900,Math.min(1800,Number(fd.get('container_max')||1240))))};await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({theme_config:JSON.stringify(theme)})});toast('Theme saved','success')})};
 $('#upload-form').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('.btn'),fd=new FormData(e.currentTarget);await runAction(btn,async()=>{const out=await api('/api/admin/media',{method:'POST',body:fd});$('#upload-result').innerHTML=`<div class="item-card"><img class="image-preview" src="${esc(out.url)}" alt="Uploaded"><div class="copy-url">${esc(out.url)}</div></div>`;toast('Image uploaded','success')})};
}
async function loadSecurity(){$('#view').innerHTML=`<div class="panel" style="max-width:600px"><h2>Change admin password</h2><p class="muted">Minimum 12 characters. Changing the password signs out all active sessions.</p><form id="password-form" style="margin-top:18px"><div class="field"><label>Current password</label><input name="current_password" type="password" required></div><div class="field"><label>New password</label><input name="new_password" type="password" minlength="12" required></div><div class="field"><label>Repeat new password</label><input name="repeat" type="password" minlength="12" required></div><button class="btn" type="submit">Change password</button><div id="pass-error" style="color:#9c4c4c;font-size:12px;margin-top:10px"></div></form></div>`;$('#password-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(fd.get('new_password')!==fd.get('repeat'))return $('#pass-error').textContent='New passwords do not match.';const btn=e.currentTarget.querySelector('button[type=submit]');await runAction(btn,async()=>{await api('/api/admin/change-password',{method:'POST',body:JSON.stringify({current_password:fd.get('current_password'),new_password:fd.get('new_password')})});alert('Password changed. Please sign in again.');location.reload()})}}
function openDetailsModal(title,body){closeDetailsModal();document.body.classList.add('sidebar-locked');const d=document.createElement('div');d.id='details-modal';d.className='modal-backdrop';d.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div class="modal-title">${esc(title)}</div><button class="close" type="button" data-details-close>×</button></div><div class="modal-body">${body}</div></div>`;document.body.appendChild(d);d.addEventListener('click',e=>{if(e.target===d||e.target.closest('[data-details-close]'))closeDetailsModal()})}
function closeDetailsModal(){document.querySelector('#details-modal')?.remove();if(!document.querySelector('#sidebar.open'))document.body.classList.remove('sidebar-locked')}
document.addEventListener('click',e=>{const r=e.target.closest('[data-admin-retry]');if(r)loadView()});
document.addEventListener('DOMContentLoaded',boot);
